function result=auditEpVarianceReplay45Selftest(root)
%AUDITEPVARIANCEREPLAY45SELFTEST Deterministic diagnostic isolation and frozen replay checks.
cfg=auditEpVarianceReplay45Config(root);directories=localFrozen(root,cfg);before=cellfun(@auditDirectoryShaManifest,directories,'UniformOutput',false);source=auditEpVarianceReplay45Preflight(cfg);
constellation=qammod((0:15).',16,'UnitAveragePower',true);H=[1 .2-.1i;.1+.3i .9];y=[.5+.2i;-.1+.4i];plain=auditEpDetectorOjcd(y,H,.1,constellation);diagnostic=auditEpDetectorOjcd(y,H,.1,constellation,captureDiagnostic=true);
checks=struct();checks.detectorOutputsExactlyEqual=isequaln(plain.posteriorMean,diagnostic.posteriorMean)&&isequaln(plain.posteriorVariance,diagnostic.posteriorVariance)&&isequaln(plain.extrinsicMean,diagnostic.extrinsicMean)&&isequaln(plain.extrinsicVariance,diagnostic.extrinsicVariance)&&isequaln(plain.bitLlr,diagnostic.bitLlr)&&isequaln(plain.lambda,diagnostic.lambda)&&isequaln(plain.gamma,diagnostic.gamma);
checks.diagFieldsPresent=all(isfield(diagnostic.diagOut,{'sigmaDiag','cavityDenominator','extrinsicVariance','extrinsicMean','posteriorVariance','posteriorMean','varianceUsedForLlr','lambdaBeforeUpdate','lambdaCandidate','bitLlr','gramRcond','precisionFloorHits','varianceFloorHits','negativePrecisionCandidates','nonfiniteCandidates','rollbackCount'}));
checks.diagFinite=all(isfinite([diagnostic.diagOut.sigmaDiag;diagnostic.diagOut.extrinsicVariance;diagnostic.diagOut.posteriorVariance;diagnostic.diagOut.bitLlr(:)]));
scenario=auditBuildPairedSnrScenario(source.sourceCfg,1);frozen=load(source.chunkPaths(1),'chunk');checks.replayScenarioHashes=isequaln(scenario.hashes,frozen.chunk.scenarioHashes);packet=auditRealizePairedSnrScenario(source.sourceCfg,scenario,18);expected=localExpected(frozen.chunk,18,"PerfectCSI_EP");checks.replayYHash=packet.sharedHashY==localExpectedY(source.receiverRows,1,18,"PerfectCSI_EP");checks.rawLlrHashFieldAvailable=isfield(expected,'rawUsefulLlr')&&numel(expected.rawUsefulLlr)==3*source.sourceCfg.ldpc.N;
checks.truthIsolation=~contains(fileread(fullfile(root,'audit_three_layer_helpers','ojcd_baseline','auditEpDetectorOjcd.m')),'codedBits')&&~contains(fileread(fullfile(root,'audit_three_layer_helpers','quality_aware_proposed','auditMechanismOnlineReceive.m')),'codedBits');
checks.covarianceAliasExact=localAlias(root);checks.noOutputCreated=exist(cfg.outputDirectory,'dir')~=7;after=cellfun(@auditDirectoryShaManifest,directories,'UniformOutput',false);checks.frozenDirectoriesUnchanged=all(cellfun(@isequal,before,after));
values=struct2array(checks);failed=string(fieldnames(checks));failed=failed(~values);assert(isempty(failed),'EP variance replay45 selftest failed: %s.',strjoin(failed,', '));result=struct('passed',true,'checks',checks,'diagnosticOnOffMaximumDifference',0,'receiverRuns',0,'physicalSeedsConsumed',0);fprintf('EP variance replay45 selftest PASS: %d/%d checks; diagnostic on/off max difference=0; receiverRuns=0; physicalSeeds=0.\n',nnz(values),numel(values));
end
function expected=localExpected(chunk,snr,method),for i=1:numel(chunk.records),x=chunk.records{i};if x.targetSnrDb==snr&&x.method==method,expected=x;return;end,end,error('Expected record missing.');end
function value=localExpectedY(T,scenario,snr,method),x=T(T.scenarioIndex==scenario&T.targetSnrDb==snr&T.method==method,:);assert(height(x)==1);value=x.sharedHashY;end
function pass=localAlias(root)
cfg=auditCovarianceAwareSnrPairedLocalization20Config(root);pilot=complex(zeros(cfg.NFFT,1,2,2,'single'));for k=1:cfg.NFFT,pilot(k,1,:,:)=single(eye(2));end
bits=zeros(2*numel(cfg.data),4);for q=1:size(bits,1),bits(q,:)=bitget(mod(q-1,16),4:-1:1);end;x=reshape(ofdm.qam16ModBits(bits),2,[]);received=complex(zeros(numel(cfg.data),1,2,'single'));for d=1:numel(cfg.data),received(d,1,:)=single(x(:,d));end
online=struct('pilotObservation',pilot,'receivedData',received,'validDataMask',true(numel(cfg.data),1),'noiseVar',cfg.noiseVar,'rho',cfg.rho);a=auditMechanismRunSingleEstimator(cfg,online,"FixedRadius3LsCovOnlyCausal_EP");b=auditMechanismRunSingleEstimator(cfg,online,"CovarianceAwareLocalDAKalmanCausal_EP");pass=isequaln(a.Hhat,b.Hhat)&&isequaln(a.finalState,b.finalState)&&isequaln(a.finalCovariance,b.finalCovariance);
end
function dirs=localFrozen(root,~)
names=["covariance_aware_final_validation50_seed20260721","covariance_aware_snr_localization10_seed20260724","covariance_aware_snr_paired_localization20_seed20260725","covariance_aware_llr_ldpc_existing_results_audit_v1","covariance_aware_llr_ldpc_replay_smoke_v1","decoder_confidence_temperature_calibration_dev12_seed20260726","decoder_confidence_raw_clipping_dev12_v1"];dirs=cellfun(@(n)fullfile(root,'results_three_layer_validation',n),cellstr(names),'UniformOutput',false);
end
